components.css:
.ds-button-primary{font-family:Poppins,sans-serif;font-size:14px;display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  border: 1px solid transparent;
  border-radius: 6px;
  padding: 13px 23px;
  font-weight: 500;
  min-height: 46px;
  transition:
    background 0.2s,
    border-color 0.2s;
  line-height: 1.4;
  white-space: normal;background: var(--blue);
  color: #fff;}.ds-button-primary:hover:not(:disabled){background: var(--blue-hover);}.ds-button-primary:focus-visible{outline:2px solid var(--accent);outline-offset:4px;}.ds-button-primary:disabled{opacity:.5;cursor:not-allowed;}@media(prefers-reduced-motion:reduce){.ds-button-primary{transition:none;}}

.ds-button-light{font-family:Poppins,sans-serif;font-size:14px;display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  border: 1px solid transparent;
  border-radius: 6px;
  padding: 13px 23px;
  font-weight: 500;
  min-height: 46px;
  transition:
    background 0.2s,
    border-color 0.2s;
  line-height: 1.4;
  white-space: normal;background: #e9e9e9;
  color: #111;}.ds-button-light:hover:not(:disabled){background: white;}.ds-button-light:focus-visible{outline:2px solid var(--accent);outline-offset:4px;}.ds-button-light:disabled{opacity:.5;cursor:not-allowed;}@media(prefers-reduced-motion:reduce){.ds-button-light{transition:none;}}

.ds-button-outline{font-family:Poppins,sans-serif;font-size:14px;display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  border: 1px solid transparent;
  border-radius: 6px;
  padding: 13px 23px;
  font-weight: 500;
  min-height: 46px;
  transition:
    background 0.2s,
    border-color 0.2s;
  line-height: 1.4;
  white-space: normal;border-color: #484848;
  background: transparent;
  color: var(--text);}.ds-button-outline:hover:not(:disabled){background: #252525;
  border-color: #777;}.ds-button-outline:focus-visible{outline:2px solid var(--accent);outline-offset:4px;}.ds-button-outline:disabled{opacity:.5;cursor:not-allowed;}@media(prefers-reduced-motion:reduce){.ds-button-outline{transition:none;}}

.ds-button-dark{font-family:Poppins,sans-serif;font-size:14px;display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  border: 1px solid transparent;
  border-radius: 6px;
  padding: 13px 23px;
  font-weight: 500;
  min-height: 46px;
  transition:
    background 0.2s,
    border-color 0.2s;
  line-height: 1.4;
  white-space: normal;background: var(--blue);
  color: white;}.ds-button-dark:focus-visible{outline:2px solid var(--accent);outline-offset:4px;}.ds-button-dark:disabled{opacity:.5;cursor:not-allowed;}@media(prefers-reduced-motion:reduce){.ds-button-dark{transition:none;}}

.ds-field-label{font-family:Poppins,sans-serif;display: block;
  font-size: 12px;
  font-weight: 500;
  color: var(--secondary);
  margin: 0 0 8px;}.ds-field{font-family:Poppins,sans-serif;font-size:14px;font: inherit;}.ds-field::placeholder{color:var(--muted)}.ds-field:focus-visible{outline:2px solid var(--accent);outline-offset:4px;}.ds-field:disabled{opacity:.5}

.ds-nav{display:grid;gap:5px}.ds-nav>button{font-family:Poppins,sans-serif;display: flex;
  align-items: center;
  gap: 11px;
  text-align: left;
  border: 0;
  color: var(--secondary);
  background: transparent;
  padding: 11px 12px;
  border-radius: 6px;
  font-size: 12px;
  min-height: 42px;}.ds-nav>button:hover{background: #202020;}.ds-nav>button[aria-current]{background: #12344c;
  color: #89cdff;}.ds-nav>button:focus-visible{outline:2px solid var(--accent);outline-offset:4px;}

.ds-incident{font-family:Poppins,sans-serif;color:var(--text);border: 1px solid var(--border);
  border-radius: 12px;
  padding: 23px;
  margin-bottom: 20px;
  background: #191919;}.ds-incident h3{font-size: 17px;
  margin: 0 0 12px;
  overflow-wrap: anywhere;font-weight:600;line-height:1.2;letter-spacing:-.015em}.ds-incident p{font-size: 12px;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  line-height: 1.85;color:var(--secondary)}
